const {
  Document, Packer, Paragraph, TextRun, HeadingLevel,
  AlignmentType, BorderStyle, WidthType, TableRow, TableCell, Table, ShadingType
} = require('docx');
const fs = require('fs');

const BLUE = "1B3A6B";
const GOLD = "C9A84C";
const DARK = "1A1A1A";
const GRAY = "555555";
const LIGHT_BLUE = "EEF2F8";

function heading1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 400, after: 140 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: GOLD, space: 8 } },
    children: [new TextRun({ text, bold: true, size: 32, color: BLUE, font: "Arial" })]
  });
}

function article(number, title) {
  return new Paragraph({
    spacing: { before: 360, after: 100 },
    children: [
      new TextRun({ text: `ARTICLE ${number} — `, bold: true, size: 26, color: GOLD, font: "Arial" }),
      new TextRun({ text: title, bold: true, size: 26, color: BLUE, font: "Arial" })
    ]
  });
}

function confession(text) {
  return new Paragraph({
    spacing: { before: 100, after: 60 },
    indent: { left: 360 },
    border: { left: { style: BorderStyle.SINGLE, size: 6, color: GOLD, space: 12 } },
    children: [new TextRun({ text, bold: true, italics: true, size: 24, color: DARK, font: "Arial" })]
  });
}

function exposition(text) {
  return new Paragraph({
    spacing: { before: 100, after: 100 },
    children: [new TextRun({ text, size: 23, color: DARK, font: "Arial" })]
  });
}

function scripture(ref, text) {
  return [
    new Paragraph({
      spacing: { before: 140, after: 40 },
      indent: { left: 720 },
      children: [new TextRun({ text: ref, bold: true, italics: true, size: 21, color: BLUE, font: "Arial" })]
    }),
    new Paragraph({
      spacing: { before: 0, after: 140 },
      indent: { left: 720, right: 360 },
      border: { left: { style: BorderStyle.SINGLE, size: 4, color: GOLD, space: 10 } },
      children: [new TextRun({ text, italics: true, size: 21, color: GRAY, font: "Arial" })]
    })
  ];
}

function spacer() {
  return new Paragraph({ spacing: { before: 80, after: 80 }, children: [new TextRun("")] });
}

function divider() {
  return new Paragraph({
    spacing: { before: 200, after: 200 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 2, color: "CCCCCC", space: 1 } },
    children: [new TextRun("")]
  });
}

function signatureLine(label) {
  return new Paragraph({
    spacing: { before: 480, after: 80 },
    children: [
      new TextRun({ text: "________________________________________________     ", size: 22, color: DARK, font: "Arial" }),
      new TextRun({ text: label, size: 20, color: GRAY, font: "Arial" })
    ]
  });
}

const doc = new Document({
  styles: {
    default: { document: { run: { font: "Arial", size: 23, color: DARK } } },
    paragraphStyles: [
      {
        id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 32, bold: true, font: "Arial", color: BLUE },
        paragraph: { spacing: { before: 400, after: 140 }, outlineLevel: 0 }
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    children: [

      // HEADER
      new Paragraph({
        spacing: { before: 0, after: 80 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "THE THESSALONIAN MANDATE INSTITUTE", bold: true, size: 40, color: BLUE, font: "Arial" })]
      }),
      new Paragraph({
        spacing: { before: 0, after: 60 },
        alignment: AlignmentType.CENTER,
        border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD, space: 6 } },
        children: [new TextRun({ text: "Austin, Texas  ·  Established under 26 U.S.C. § 508(c)(1)(A)", size: 20, color: GRAY, font: "Arial" })]
      }),
      spacer(),
      new Paragraph({
        spacing: { before: 80, after: 40 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "STATEMENT OF FAITH", bold: true, size: 44, color: DARK, font: "Arial" })]
      }),
      new Paragraph({
        spacing: { before: 0, after: 200 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "The Doctrinal Confession of This Organization", italics: true, size: 24, color: GRAY, font: "Arial" })]
      }),

      // PREAMBLE
      new Paragraph({
        spacing: { before: 160, after: 160 },
        shading: { fill: LIGHT_BLUE, type: ShadingType.CLEAR },
        border: {
          top: { style: BorderStyle.SINGLE, size: 4, color: BLUE, space: 6 },
          bottom: { style: BorderStyle.SINGLE, size: 4, color: BLUE, space: 6 },
          left: { style: BorderStyle.SINGLE, size: 4, color: BLUE, space: 6 },
          right: { style: BorderStyle.SINGLE, size: 4, color: BLUE, space: 6 }
        },
        indent: { left: 240, right: 240 },
        children: [new TextRun({
          text: "We, the members and leadership of The Thessalonian Mandate Institute, do hereby confess and affirm the following articles of faith as the sincere, voluntary, and binding doctrinal foundation of this organization. These convictions are not assumed for convenience or legal advantage. They are held because they are true — true to the Word of God, true to the historic Christian faith, and true to the urgent need of the present hour. This Statement of Faith shall govern all operations, programs, and activities of this organization.",
          size: 22, color: DARK, font: "Arial", italics: true
        })]
      }),

      divider(),

      // ARTICLE I
      article("I", "THE HOLY SCRIPTURES"),
      confession("We believe the Holy Bible, consisting of the sixty-six books of the Old and New Testaments, to be the inspired, inerrant, and authoritative Word of God — the supreme and final standard for all matters of faith, doctrine, and practice."),
      exposition("The Scriptures are not merely ancient wisdom literature or a collection of religious tradition. They are the living Word of the living God, breathed out by the Holy Spirit through human authors, and preserved for the instruction, correction, and equipping of God's people in every generation. The doctrinal positions of this organization are derived from and answerable to the biblical text. No tradition, no cultural pressure, and no legal consideration supersedes the authority of Scripture in the life of this organization."),
      ...scripture("2 Timothy 3:16-17 (NIV)", "All Scripture is God-breathed and is useful for teaching, rebuking, correcting and training in righteousness, so that the servant of God may be thoroughly equipped for every good work."),

      divider(),

      // ARTICLE II
      article("II", "THE NATURE OF GOD"),
      confession("We believe in one God, eternally existing in three Persons — Father, Son, and Holy Spirit — co-equal, co-eternal, and co-substantial; the Creator and Sustainer of all things, sovereign over history, and intimately present in the lives of those who seek Him."),
      exposition("The God who commands work in 2 Thessalonians 3:10 is the same God who worked in creation (Genesis 1), who established human vocation in the garden (Genesis 2:15), and who entered the human experience as a carpenter (Mark 6:3). The doctrine of God is not peripheral to our mission — it is its source. We work because God works. We equip others to work because God equips His people for every good work (2 Timothy 3:17). The mandate flows from the nature of the One who issued it."),
      ...scripture("Deuteronomy 6:4 (NIV)", "Hear, O Israel: The Lord our God, the Lord is one."),

      divider(),

      // ARTICLE III
      article("III", "THE DIGNITY OF HUMANITY"),
      confession("We believe that human beings are created in the image and likeness of God — the Imago Dei — and that this image confers upon every person an inherent, inviolable dignity that no economic force, technological disruption, or social circumstance can diminish or destroy."),
