    paragraphStyles: [
      {
        id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 30, bold: true, font: "Arial", color: BLUE },
        paragraph: { spacing: { before: 480, after: 160 }, outlineLevel: 0 }
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    children: [

      // COVER
      new Paragraph({
        spacing: { before: 720, after: 120 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "THE THESSALONIAN MANDATE INSTITUTE", bold: true, size: 44, color: BLUE, font: "Arial" })]
      }),
      new Paragraph({
        spacing: { before: 0, after: 80 },
        alignment: AlignmentType.CENTER,
        border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD, space: 6 } },
        children: [new TextRun({ text: "Austin, Texas", size: 22, color: GRAY, font: "Arial" })]
      }),
      spacer(),
      new Paragraph({
        spacing: { before: 120, after: 80 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "BYLAWS", bold: true, size: 52, color: DARK, font: "Arial" })]
      }),
      new Paragraph({
        spacing: { before: 0, after: 80 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "A Faith-Based Organization", italics: true, size: 26, color: GRAY, font: "Arial" })]
      }),
      new Paragraph({
        spacing: { before: 0, after: 80 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "Established under 26 U.S.C. § 508(c)(1)(A)", size: 22, color: GRAY, font: "Arial" })]
      }),
      spacer(),
      new Paragraph({
        spacing: { before: 80, after: 1200 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "\"The one who is willing to work shall be equipped to work.\"", italics: true, size: 22, color: GRAY, font: "Arial" })]
      }),

      divider(),

      // PREAMBLE
      heading1("PREAMBLE"),
      body("These Bylaws govern the internal operations of The Thessalonian Mandate Institute, a Faith-Based Organization organized and operating under the automatic tax exemption provided by 26 U.S.C. § 508(c)(1)(A). This organization is not a 501(c)(3) organization and has not applied for IRS determination. Its exempt status derives directly and automatically from the provisions of the Internal Revenue Code applicable to faith-based organizations."),
      body("All operations of this organization are subordinate to and governed by the theological convictions set forth in the Statement of Faith and the Theological Framework of this organization. In any conflict between these Bylaws and those foundational documents, the theological documents shall control as to matters of mission and doctrine, and these Bylaws shall control as to matters of internal governance."),

      divider(),

      // ARTICLE I
      article("I", "NAME, NATURE, AND PRINCIPAL OFFICE"),

      section("1.1", "Name"),
      body("The name of this organization is The Thessalonian Mandate Institute (hereinafter \"the Institute\" or \"the Organization\")."),

      section("1.2", "Nature"),
      body("The Institute is a Faith-Based Organization operating pursuant to the sincere religious convictions of its founders and leadership, as set forth in its Statement of Faith. The Institute holds that the obligation to work is a divine mandate rooted in scripture, and that equipping displaced workers with the skills necessary to fulfill that mandate is an act of religious ministry. All programs, activities, and operations of the Institute flow from and are governed by this theological conviction."),

      section("1.3", "Principal Office"),
      body("The principal office of the Institute shall be located in Austin, Travis County, Texas. The Board of Directors may change the principal office or establish additional offices as ministry needs require."),

      section("1.4", "Registered Agent"),
      body("The Institute shall maintain a registered agent in the State of Texas as required by applicable law. The identity of the registered agent may be changed by resolution of the Board of Directors."),

      divider(),

      // ARTICLE II
      article("II", "MISSION AND PURPOSE"),

      section("2.1", "Primary Mission"),
      body("The primary mission of the Institute is to restore displaced workers to the dignity of productive, skilled, and purposeful labor by equipping them with the technical knowledge and professional capabilities necessary to participate fully in the modern economy — in obedience to the work mandate of 2 Thessalonians 3:10 and in fulfillment of the theological standard of skilled excellence set forth in Proverbs 22:29."),

      section("2.2", "Theological Purpose"),
      body("The Institute understands the mass displacement of workers by automation and artificial intelligence as a spiritual crisis — a crisis of vocation — that demands a theological response. The Institute exists to provide that response. All activities of the Institute are conducted as acts of religious ministry, grounded in the sincere theological convictions of its founders."),

      section("2.3", "Program Purpose"),
      body("In furtherance of its mission, the Institute may engage in the following activities:"),
      numbered(1, "Providing instruction in technology fields including but not limited to information technology, cybersecurity, cloud computing, data analysis, and AI-assisted workflow management;"),
      numbered(2, "Developing and delivering curriculum aligned with industry-recognized certification pathways;"),
      numbered(3, "Establishing cohort-based learning communities that provide mutual support and accountability to participants;"),
      numbered(4, "Providing job placement assistance, mentorship, and post-program support to graduates;"),
      numbered(5, "Conducting research, publishing, and public education on the theological dimensions of work, vocation, and technological displacement;"),
      numbered(6, "Receiving donations, grants, and other contributions in support of the foregoing activities;"),
      numbered(7, "Acquiring, holding, and managing property and assets in furtherance of the mission; and"),
      numbered(8, "Engaging in any other activity consistent with the theological mission of the Institute."),

      section("2.4", "Non-Discrimination in Program Participation"),
      body("The Institute shall admit participants to its programs without regard to race, color, national origin, sex, age, or disability. The Institute may, consistent with its religious convictions, establish program requirements related to conduct, commitment, and participation that apply uniformly to all participants."),

      divider(),

      // ARTICLE III
      article("III", "THEOLOGICAL GOVERNANCE"),

      section("3.1", "Supremacy of Theological Foundation"),
      body("The Statement of Faith and the Theological Framework of the Institute are the supreme governing documents of this organization with respect to matters of doctrine, mission, and religious conviction. No action of the Board of Directors, the Minister, or any officer shall contradict, undermine, or depart from the theological foundations of the Institute."),

      section("3.2", "Minister Designation"),
      body("The founder and Chief Executive of the Institute shall hold the title of Minister and shall be recognized as the primary religious leader of this organization for all purposes, including but not limited to eligibility for the minister's housing allowance under 26 U.S.C. § 107. The Board of Directors may designate additional persons as Ministers of the Institute as ministry needs require."),

      section("3.3", "Religious Liberty Protection"),
      body("The Institute claims the full protection of the First Amendment to the United States Constitution and of all applicable federal and state religious liberty statutes in the conduct of its operations. The Institute shall not be required to act contrary to its sincerely held religious convictions in any aspect of its operations."),

      section("3.4", "Faith-Based Hiring"),
      body("Consistent with its status as a faith-based organization and the protections afforded by applicable law, the Institute may require that all employees, contractors, and volunteers affirm the Statement of Faith of the Institute and commit to conduct their service in a manner consistent with the theological convictions of the Institute."),

      divider(),

      // ARTICLE IV
      article("IV", "BOARD OF DIRECTORS"),

      section("4.1", "Authority"),
      body("The Board of Directors (hereinafter \"the Board\") shall be the governing body of the Institute, responsible for oversight of the organization's operations, finances, and strategic direction, subject to the theological supremacy established in Article III."),

      section("4.2", "Composition"),
      body("The Board shall consist of not fewer than one (1) and not more than seven (7) Directors. The initial Board shall consist of the Founder, who shall serve as sole Director until such time as additional Directors are appointed. The Board may increase or decrease the number of Directors by resolution, within the limits stated herein."),

      section("4.3", "Qualifications"),
      body("All Directors must:"),
      lettered("a", "Be at least eighteen (18) years of age;"),
      lettered("b", "Affirm the Statement of Faith of the Institute;"),
      lettered("c", "Commit to act in the best interest of the Institute and its mission; and"),
      lettered("d", "Have no undisclosed conflict of interest that would impair their ability to serve."),

      section("4.4", "Terms"),
      body("Directors shall serve terms of two (2) years and may be re-appointed without limitation. Initial Directors appointed at formation shall serve until their successors are appointed. Terms shall be staggered where the Board has three or more Directors, so that continuity of governance is maintained."),

      section("4.5", "Appointment and Removal"),
      body("Directors shall be appointed by a majority vote of the existing Board. A Director may be removed by a two-thirds (2/3) vote of the remaining Directors for cause, including but not limited to breach of fiduciary duty, conduct inconsistent with the Statement of Faith, or failure to participate in Board activities."),

      section("4.6", "Resignation"),
      body("A Director may resign at any time by delivering written notice to the Chair of the Board or the Minister. Resignation is effective upon delivery unless a later date is specified."),

      section("4.7", "Vacancies"),
      body("Vacancies on the Board shall be filled by appointment of the remaining Directors. A Director appointed to fill a vacancy shall serve the remainder of the unexpired term."),

      section("4.8", "Meetings"),
      body("The Board shall meet not less than twice per calendar year. Special meetings may be called by the Chair, the Minister, or any two Directors. Meetings may be conducted in person, by telephone, or by videoconference. Notice of any meeting shall be provided not less than five (5) days in advance, except in cases of genuine emergency."),

      section("4.9", "Quorum and Voting"),
      body("A majority of the Directors then serving shall constitute a quorum for the transaction of business. Actions of the Board require the affirmative vote of a majority of Directors present at a meeting at which a quorum is present, unless a higher threshold is specified elsewhere in these Bylaws."),

      section("4.10", "Action Without Meeting"),
      body("The Board may act without a meeting by written consent signed by all Directors then serving. Such consent shall be filed with the records of the Institute."),

      section("4.11", "Compensation"),
      body("Directors shall serve without compensation for their service as Directors. Directors may be reimbursed for reasonable expenses incurred in the performance of their duties. Directors who also serve as employees or Ministers of the Institute may receive compensation in those capacities, provided such compensation is approved by disinterested Directors and is reasonable."),

      divider(),

      // ARTICLE V
      article("V", "OFFICERS"),

      section("5.1", "Officers"),
      body("The officers of the Institute shall be a Minister/Chief Executive, a Secretary, and a Treasurer. The Board may create additional officer positions as needed. One person may hold more than one office, except that the same person may not serve simultaneously as both Secretary and Treasurer if the Board has three or more Directors."),

      section("5.2", "Minister / Chief Executive"),
      body("The Minister shall be the chief executive and primary religious leader of the Institute. The Minister shall:"),
      lettered("a", "Exercise general supervision over the operations of the Institute;"),
      lettered("b", "Implement the strategic direction established by the Board;"),
      lettered("c", "Serve as the primary spokesperson and representative of the Institute;"),
      lettered("d", "Preside at programs and events of the Institute;"),
      lettered("e", "Execute contracts and instruments on behalf of the Institute as authorized by the Board; and"),
      lettered("f", "Perform such other duties as the Board may assign."),

      section("5.3", "Secretary"),
      body("The Secretary shall maintain the records of the Institute, including minutes of Board meetings, official correspondence, and the governing documents of the organization. The Secretary shall provide notice of meetings and perform such other duties as the Board may assign."),

      section("5.4", "Treasurer"),
      body("The Treasurer shall oversee the financial affairs of the Institute, including maintenance of accurate financial records, preparation of financial reports for the Board, and oversight of the Institute's banking relationships and financial accounts. The Treasurer shall perform such other duties as the Board may assign."),

      section("5.5", "Appointment and Removal"),
      body("Officers shall be appointed by the Board and shall serve at the pleasure of the Board. An officer may be removed by a majority vote of the Board with or without cause."),

      divider(),

      // ARTICLE VI
      article("VI", "FINANCIAL MANAGEMENT"),

      section("6.1", "Fiscal Year"),
      body("The fiscal year of the Institute shall begin on January 1 and end on December 31 of each calendar year, unless the Board establishes a different fiscal year by resolution."),

      section("6.2", "Financial Accounts"),
      body("The Institute shall maintain one or more bank accounts in the name of the Institute. Withdrawals from Institute accounts shall require the signature or authorization of the Minister or Treasurer, or such other persons as the Board may designate by resolution."),

      section("6.3", "Financial Reserves and Investment"),
      body("The Institute may maintain financial reserves and invest its assets in any manner consistent with its fiduciary obligations and its theological mission. The Institute may hold whole life insurance policies as an asset of the organization, using the cash value thereof as an operating reserve and treasury instrument, and may borrow against such policies in furtherance of the mission of the Institute. Such arrangements shall be approved by the Board and documented in Board minutes."),

      section("6.4", "Compensation of Minister"),
      body("The Minister of the Institute may receive reasonable compensation for services rendered to the Institute, including a housing allowance as provided under 26 U.S.C. § 107. Any housing allowance shall be formally designated by the Board in advance of the period to which it applies, and shall not exceed the lesser of: (a) the actual cost of housing, (b) the fair rental value of the housing, or (c) the reasonable compensation of the Minister. Such designation shall be documented in the minutes of the Board."),

      section("6.5", "Conflicts of Interest"),
      body("Directors, officers, and employees of the Institute shall disclose any actual or potential conflict of interest in any matter before the Board. An interested party shall not participate in the vote on any matter in which they have a conflict of interest. The Institute shall maintain a written Conflict of Interest Policy."),

      section("6.6", "No Private Inurement"),
      body("No part of the net earnings of the Institute shall inure to the benefit of any private individual, except as reasonable compensation for services actually rendered. This provision shall be interpreted and enforced in a manner consistent with the requirements applicable to tax-exempt organizations."),

      section("6.7", "Dissolution"),
      body("In the event of dissolution of the Institute, after payment of all liabilities, the remaining assets shall be distributed to one or more faith-based organizations sharing a similar theological mission, as determined by the Board. No assets shall be distributed to any private individual upon dissolution."),

      divider(),

      // ARTICLE VII
      article("VII", "RECORDS AND REPORTING"),

      section("7.1", "Corporate Records"),
      body("The Institute shall maintain the following records at its principal office or at a location accessible to the Board:"),
      lettered("a", "These Bylaws and all amendments thereto;"),
      lettered("b", "The Statement of Faith and Theological Framework;"),
      lettered("c", "Minutes of all Board meetings and actions taken without a meeting;"),
      lettered("d", "Financial records sufficient to reflect the Institute's financial condition; and"),
      lettered("e", "All contracts, agreements, and correspondence material to the operations of the Institute."),

      section("7.2", "Financial Reporting"),
      body("The Treasurer shall provide the Board with a financial report at each regular meeting of the Board. An annual financial summary shall be prepared within ninety (90) days after the close of each fiscal year."),

      section("7.3", "Filing Requirements"),
      body("As an organization exempt under 26 U.S.C. § 508(c)(1)(A), the Institute is not required to file Form 990 or to obtain a determination letter from the Internal Revenue Service. The Institute shall nonetheless comply with all applicable state registration and reporting requirements and shall file any federal forms required of organizations in its category."),

      divider(),

      // ARTICLE VIII
      article("VIII", "INDEMNIFICATION"),

      section("8.1", "Indemnification of Directors and Officers"),
      body("The Institute shall indemnify its Directors, officers, and employees against claims, liabilities, and expenses arising from their service to the Institute, to the fullest extent permitted by applicable law, provided that the person acted in good faith and in a manner reasonably believed to be in the best interest of the Institute. The Institute may purchase insurance to fund its indemnification obligations."),

      section("8.2", "Limitation"),
      body("No indemnification shall be provided for conduct that constitutes fraud, willful misconduct, or a knowing violation of law."),

      divider(),

      // ARTICLE IX
      article("IX", "AMENDMENTS"),

      section("9.1", "Amendment of Bylaws"),
      body("These Bylaws may be amended by a two-thirds (2/3) vote of the Board at any regular or special meeting, provided that notice of the proposed amendment has been given to all Directors not less than ten (10) days prior to the meeting. No amendment shall alter or undermine the theological foundations of the Institute as set forth in the Statement of Faith and Theological Framework."),

      section("9.2", "Amendment of Theological Documents"),
      body("The Statement of Faith and Theological Framework may be amended only by unanimous vote of the full Board, provided that any amendment must be consistent with and shall not depart from the core theological convictions of the Institute regarding the divine mandate of work, the dignity of human labor, and the mission of equipping displaced workers."),

      divider(),

      // ARTICLE X
      article("X", "MISCELLANEOUS"),

      section("10.1", "Parliamentary Authority"),
      body("In matters of procedure not addressed by these Bylaws, the Board may refer to Robert's Rules of Order (current edition) as a guide, but is not bound thereby."),

      section("10.2", "Severability"),
      body("If any provision of these Bylaws is found to be invalid or unenforceable under applicable law, such provision shall be severed from the remainder, which shall continue in full force and effect."),

      section("10.3", "Governing Law"),
      body("These Bylaws shall be governed by the laws of the State of Texas, except to the extent that federal law or the First Amendment to the United States Constitution provides greater protection for the religious liberty of this organization."),

      section("10.4", "Construction"),
      body("These Bylaws shall be construed in light of the theological mission and religious convictions of the Institute. Any ambiguity shall be resolved in the manner most consistent with the Statement of Faith and the Theological Framework of the Institute."),

      divider(),

      // ADOPTION
      heading1("ADOPTION"),

      body("These Bylaws are hereby adopted as the governing Bylaws of The Thessalonian Mandate Institute by the undersigned, constituting the initial Board of Directors of this organization."),

      spacer(),

      sigLine("Founder / Minister — Printed Name"),
      new Paragraph({
        spacing: { before: 0, after: 320 },
        children: [new TextRun({ text: "________________________________________________     Date: _______________", size: 21, color: DARK, font: "Arial" })]
      }),

      spacer(),
