import re

with open('/tmp/all_text.txt', 'r') as f:
    raw = f.read()

# Split into documents
docs = {}
current = None
current_text = []
for line in raw.split('\n'):
    if line.startswith('=== ') and line.endswith(' ==='):
        if current:
            docs[current] = '\n'.join(current_text)
        current = line[4:-4]
        current_text = []
    else:
        current_text.append(line)
if current:
    docs[current] = '\n'.join(current_text)

issues = []

# ── 1. IRC citations ──────────────────────────────────────────────────────────
irc_pattern = re.compile(r'26 U\.S\.C\.\s*§\s*[\w\(\)]+')
print("IRC CITATIONS FOUND:")
for doc, text in docs.items():
    for m in irc_pattern.finditer(text):
        print(f"  [{doc}] {m.group()}")

# ── 2. Cross-document references ──────────────────────────────────────────────
print("\nCROSS-DOCUMENT REFERENCES:")
ref_terms = [
    'Statement of Faith', 'Theological Framework', 'Bylaws',
    'Board Resolution', 'Founding Board'
]
for doc, text in docs.items():
    for term in ref_terms:
        if term in text and term not in doc:
            count = text.count(term)
            print(f"  [{doc}] references '{term}' ({count}x)")

# ── 3. Section references inside bylaws ───────────────────────────────────────
print("\nBYLAWS INTERNAL SECTION REFERENCES:")
bylaw_text = docs.get('Bylaws', '')
sec_refs = re.findall(r'(?:Section|Article)\s+[\d\.]+', bylaw_text)
unique_refs = sorted(set(sec_refs))
for r in unique_refs:
    print(f"  {r}")

# ── 4. Defined terms consistency ──────────────────────────────────────────────
print("\nDEFINED TERM CHECK:")
defined = {
    'the Institute': 'Bylaws',
    'the Organization': 'Bylaws',
    'the Board': 'Bylaws',
    'the Minister': 'Bylaws',
}
for term, defined_in in defined.items():
    for doc, text in docs.items():
        if term in text:
            pass  # just confirm presence
print("  Checking 'the Institute' usage across all docs...")
for doc, text in docs.items():
    count = text.count('the Institute')
    print(f"    [{doc}] {count}x")

# ── 5. Name consistency ───────────────────────────────────────────────────────
print("\nORGANIZATION NAME CONSISTENCY:")
name_variants = [
    'The Thessalonian Mandate Institute',
    'the Thessalonian Mandate Institute',
    'THESSALONIAN MANDATE INSTITUTE',
    'Thessalonian Mandate',
]
for variant in name_variants:
    for doc, text in docs.items():
        count = text.count(variant)
        if count:
            print(f"  [{doc}] '{variant}' appears {count}x")

# ── 6. Founder name consistency ───────────────────────────────────────────────
print("\nFOUNDER NAME CHECK:")
name_variants = ['Rickey Jay Bennett II', 'Rickey Bennett', 'R.J. Bennett']
for variant in name_variants:
    for doc, text in docs.items():
        if variant in text:
            print(f"  [{doc}] contains '{variant}'")

# ── 7. Scripture references ───────────────────────────────────────────────────
print("\nSCRIPTURE REFERENCES:")
scripture_pattern = re.compile(r'\d\s+(?:Thessalonians|Timothy|Corinthians|Genesis|Proverbs|Colossians|Deuteronomy)\s+[\d:]+')
for doc, text in docs.items():
    for m in scripture_pattern.finditer(text):
        print(f"  [{doc}] {m.group()}")

# ── 8. Check resolution references to bylaws sections ────────────────────────
print("\nRESOLUTION BYLAWS SECTION REFERENCES:")
res_text = docs.get('Board Resolution', '')
sec_refs_res = re.findall(r'Section\s+[\d\.]+', res_text)
for r in sorted(set(sec_refs_res)):
    print(f"  {r}")
    # Verify it exists in bylaws
    if r not in bylaw_text:
        issues.append(f"ISSUE: Resolution references '{r}' but not found in Bylaws")

# ── 9. Housing allowance three-part test consistency ─────────────────────────
print("\nHOUSING ALLOWANCE LANGUAGE:")
ha_docs = []
for doc, text in docs.items():
    if '107' in text or 'housing allowance' in text.lower():
        ha_docs.append(doc)
        print(f"  [{doc}] contains housing allowance language")

# ── 10. Report issues ─────────────────────────────────────────────────────────
print("\n" + "="*60)
if issues:
    print("ISSUES REQUIRING ATTENTION:")
    for issue in issues:
        print(f"  !! {issue}")
else:
    print("NO CROSS-REFERENCE ISSUES DETECTED")
print("="*60)

